def bestanden(noten):
    if len(noten) == 0:
        return False
    summe = 0
    for n in noten:
        summe += n
    return summe / len(noten) <= 4

test-8.a3:
def durchschnitte(matrix):
    ergebnis = []
    for zeile in matrix:
        summe = 0
        for wert in zeile:
            summe += wert
        ergebnis.append(summe / len(zeile))
    return ergebnis
